def count_permutations(n, k, p):
    MOD = p

    @lru_cache(None)
    def dp(i, last, asc):
        if i == n:
            return 1
        res = 0
        for j in range(1, n + 1):
            if (asc and j > last) or (not asc and j < last):
                continue
            if abs(j - last) <= k:
                res += dp(i + 1, j, asc)
                res %= MOD
        return res

    total = 0
    for start in range(1, n + 1):
        total += dp(1, start, True)
        total += dp(1, start, False)
        total %= MOD
    return total

