def count_permutations(n, k, p):
    @lru_cache(None)
    def dp(mask, last, length):
        if length == n:
            return 1
        count = 0
        for i in range(1, n + 1):
            if mask & (1 << i) == 0:
                if length == 0 or abs(i - last) <= k:
                    count += dp(mask | (1 << i), i, length + 1)
        return count % p

    return dp(0, 0, 0)

